// 📁 src/app/core/models/search.interface.ts

import {  ExperienceType, AmenityType } from './property.interface';

export interface SearchParams {
  destination: string;
  checkIn: string;
  checkOut: string;
  guests: number;
}


export interface ExperienceFilters {
  coffeTour: boolean;
  hiking: boolean;
  birdwatching: boolean;
  thermalSprings: boolean;
}

export interface AmenityFilters {
  wifi: boolean;
  parking: boolean;
  pool: boolean;
  kitchen: boolean;
  breakfast: boolean;
}

export interface Filters {
  experiences: ExperienceFilters;
  amenities: AmenityFilters;
  minRating: number;
  priceMin: number;
  priceMax: number;
}

export interface FilterState {
  activeFilters: Filters;
  hasActiveFilters: boolean;
}

export interface SortOption {
  value: string;
  label: string;
}

export const SORT_OPTIONS: SortOption[] = [
  { value: 'relevance', label: 'Más Relevantes' },
  { value: 'price-asc', label: 'Precio: Menor a Mayor' },
  { value: 'price-desc', label: 'Precio: Mayor a Menor' },
  { value: 'rating', label: 'Mejor Calificados' },
  { value: 'reviews', label: 'Más Reseñas' }
];

export interface SearchResultsConfig {
  viewMode: 'list' | 'map';
  sortBy: string;
  itemsPerPage: number;
  currentPage: number;
}
